        private static void ConfigureKpiCard(
            DevExpress.XtraEditors.PanelControl card,
            System.Windows.Forms.Panel accent,
            System.Windows.Forms.Label value,
            System.Windows.Forms.Label title,
            System.Windows.Forms.Panel badge,
            System.Windows.Forms.Label icon,
            string caption,
            string iconText)
        {
            // Kartları belirgin yapmak için Simple border ve aralarında boşluk için Margin (8px)
            card.BorderStyle =
                DevExpress.XtraEditors.Controls.BorderStyles.Simple;

            card.Dock =
                System.Windows.Forms.DockStyle.Fill;

            card.Margin =
                new System.Windows.Forms.Padding(8);

            card.Padding =
                new System.Windows.Forms.Padding(0);

            card.Controls.Add(accent);
            card.Controls.Add(value);
            card.Controls.Add(title);
            card.Controls.Add(badge);

            accent.Dock =
                System.Windows.Forms.DockStyle.Left;

            accent.Width =
                4;

            value.AutoSize =
                false;

            value.Location =
                new System.Drawing.Point(18, 10);

            value.Size =
                new System.Drawing.Size(180, 32);

            value.Text =
                "-";

            value.TextAlign =
                System.Drawing.ContentAlignment.MiddleLeft;

            value.Font =
                new System.Drawing.Font(
                    "Segoe UI",
                    18F,
                    System.Drawing.FontStyle.Bold);

            title.AutoSize =
                false;

            title.Location =
                new System.Drawing.Point(18, 45);

            title.Size =
                new System.Drawing.Size(210, 18);

            title.Text =
                caption;

            title.TextAlign =
                System.Drawing.ContentAlignment.MiddleLeft;

            title.Font =
                new System.Drawing.Font(
                    "Segoe UI",
                    7.5F,
                    System.Drawing.FontStyle.Bold);

            badge.Anchor =
                System.Windows.Forms.AnchorStyles.Top |
                System.Windows.Forms.AnchorStyles.Right;

            badge.Location =
                new System.Drawing.Point(
                    card.Width - 46,
                    12);

            badge.Size =
                new System.Drawing.Size(
                    32,
                    32);

            badge.Controls.Add(icon);

            icon.Dock =
                System.Windows.Forms.DockStyle.Fill;

            icon.Font =
                new System.Drawing.Font(
                    "Segoe UI Emoji",
                    12F);

            icon.Text =
                iconText;

            icon.TextAlign =
                System.Drawing.ContentAlignment.MiddleCenter;

            card.Resize += (_, _) =>
            {
                badge.Location =
                    new System.Drawing.Point(
                        card.ClientSize.Width -
                        badge.Width -
                        14,
                        12);
            };
        }

        private static void ConfigureChartPanel(
            DevExpress.XtraEditors.PanelControl panel,
            System.Windows.Forms.Label title,
            DevExpress.XtraCharts.ChartControl chart,
            string caption)
        {
            // Grafik panellerini de belirgin kartlar haline getirip aralarına boşluk ekledik
            panel.BorderStyle =
                DevExpress.XtraEditors.Controls.BorderStyles.Simple;

            panel.Dock =
                System.Windows.Forms.DockStyle.Fill;

            panel.Margin =
                new System.Windows.Forms.Padding(8);

            panel.Padding =
                new System.Windows.Forms.Padding(
                    12,
                    40,
                    12,
                    12);

            panel.Controls.Add(chart);
            panel.Controls.Add(title);

            title.AutoSize =
                false;

            title.Location =
                new System.Drawing.Point(14, 10);

            title.Size =
                new System.Drawing.Size(350, 24);

            title.Text =
                caption;

            title.Font =
                new System.Drawing.Font(
                    "Segoe UI",
                    10F,
                    System.Drawing.FontStyle.Bold);

            chart.Dock =
                System.Windows.Forms.DockStyle.Fill;

            chart.BorderOptions.Visibility =
                DevExpress.Utils.DefaultBoolean.False;

            chart.Legend.EnableAntialiasing =
                DevExpress.Utils.DefaultBoolean.True;
        }
